describe('Payment Flow - Card Details and Purchase Completion', () => {
  const testData = {
    cardholderName: 'John Doe',
    cardNumber: '4532015112830366',
    expiryMonth: '12',
    expiryYear: '2025',
    cvv: '123',
    email: 'john.doe@example.com',
    amount: '99.99'
  };

  const invalidCardData = {
    cardNumber: '1234567890123456',
    cvv: '12'
  };

  beforeEach(() => {
    cy.visit('/checkout');
    cy.get('[data-testid="payment-form"]').should('be.visible');
  });

  it('should successfully complete a purchase with valid card details', () => {
    // Fill in cardholder name
    cy.get('[data-testid="cardholder-name"]')
      .type(testData.cardholderName)
      .should('have.value', testData.cardholderName);

    // Fill in card number
    cy.get('[data-testid="card-number"]')
      .type(testData.cardNumber)
      .should('have.value', testData.cardNumber);

    // Fill in expiry month
    cy.get('[data-testid="expiry-month"]')
      .select(testData.expiryMonth)
      .should('have.value', testData.expiryMonth);

    // Fill in expiry year
    cy.get('[data-testid="expiry-year"]')
      .select(testData.expiryYear)
      .should('have.value', testData.expiryYear);

    // Fill in CVV
    cy.get('[data-testid="cvv"]')
      .type(testData.cvv)
      .should('have.value', testData.cvv);

    // Fill in email
    cy.get('[data-testid="email"]')
      .type(testData.email)
      .should('have.value', testData.email);

    // Verify order amount is displayed
    cy.get('[data-testid="order-amount"]')
      .should('contain', testData.amount);

    // Accept terms and conditions
    cy.get('[data-testid="terms-checkbox"]')
      .check()
      .should('be.checked');

    // Submit payment form
    cy.get('[data-testid="submit-payment-btn"]')
      .click();

    // Verify payment processing
    cy.get('[data-testid="loading-spinner"]', { timeout: 10000 })
      .should('be.visible');

    // Verify success message
    cy.get('[data-testid="success-message"]', { timeout: 15000 })
      .should('be.visible')
      .and('contain', 'Payment successful');

    // Verify order confirmation details
    cy.get('[data-testid="order-confirmation"]')
      .should('be.visible');

    cy.get('[data-testid="confirmation-email"]')
      .should('contain', testData.email);

    // Verify redirect to order confirmation page
    cy.url().should('include', '/order-confirmation');

    // Verify order number is displayed
    cy.get('[data-testid="order-number"]')
      .should('be.visible')
      .and('match', /^ORD-\d{10}$/);
  });

  it('should display validation errors for invalid card details', () => {
    // Attempt to submit empty form
    cy.get('[data-testid="submit-payment-btn"]')
      .click();

    // Verify cardholder name error
    cy.get('[data-testid="cardholder-name-error"]')
      .should('be.visible')
      .and('contain', 'Cardholder name is required');

    // Verify card number error
    cy.get('[data-testid="card-number-error"]')
      .should('be.visible')
      .and('contain', 'Card number is required');

    // Verify CVV error
    cy.get('[data-testid="cvv-error"]')
      .should('be.visible')
      .and('contain', 'CVV is required');

    // Fill in invalid card number
    cy.get('[data-testid="card-number"]')
      .type(invalidCardData.cardNumber);

    cy.get('[data-testid="submit-payment-btn"]')
      .click();

    // Verify invalid card number error
    cy.get('[data-testid="card-number-error"]')
      .should('be.visible')
      .and('contain', 'Invalid card number');

    // Fill in invalid CVV (too short)
    cy.get('[data-testid="cvv"]')
      .type(invalidCardData.cvv);

    cy.get('[data-testid="submit-payment-btn"]')
      .click();

    // Verify invalid CVV error
    cy.get('[data-testid="cvv-error"]')
      .should('be.visible')
      .and('contain', 'CVV must be 3 or 4 digits');

    // Verify terms checkbox error
    cy.get('[data-testid="terms-error"]')
      .should('be.visible')
      .and('contain', 'You must accept the terms and conditions');

    // Verify form is still on checkout page
    cy.url().should('include', '/checkout');
  });

  it('should handle network errors gracefully during payment processing', () => {
    // Fill in valid card details
    cy.get('[data-testid="cardholder-name"]')
      .type(testData.cardholderName);

    cy.get('[data-testid="card-number"]')
