    cy.get('[data-testid="expiry-month"]')
      .select(testData.expiryMonth);

    cy.get('[data-testid="expiry-year"]')
      .select(testData.expiryYear);

    cy.get('[data-testid="cvv"]')
      .type(testData.cvv);

    cy.get('[data-testid="email"]')
      .type(testData.email);

    cy.get('[data-testid="terms-checkbox"]')
      .check();

    // Intercept payment API and simulate network error
    cy.intercept('POST', '/api/payments', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('paymentError');

    cy.get('[data-testid="submit-payment-btn"]')
      .click();

    cy.wait('@paymentError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]', { timeout: 10000 })
      .should('be.visible')
      .and('contain', 'Payment processing failed');

    // Verify retry button is available
    cy.get('[data-testid="retry-payment-btn"]')
      .should('be.visible');

    // Verify form data is preserved
    cy.get('[data-testid="cardholder-name"]')
      .should('have.value', testData.cardholderName);

    cy.get('[data-testid="email"]')
      .should('have.value', testData.email);
  });

